```go
func (sips SourceIPExtractor) getIP(r *http.Request) []string {
	var addresses []string

	// Use the custom regex only if it was setup
	if sips.header != "" {
		hdr := r.Header.Get(sips.header)
		if hdr == "" {
			return nil
		}
		var allMatches [][]string
		if sips.extractAllHosts {
			allMatches = sips.regex.FindAllStringSubmatch(hdr, -1)
		} else {
			allMatches = sips.regex.FindAllStringSubmatch(hdr, 1)
		}
		if len(allMatches) == 0 {
			return nil
		}
		for _, match := range allMatches {
			// Check there is at least 1 submatch
			if len(match) < 2 {
				continue
			}
			addresses = append(addresses, match[1])
		}
		return addresses
	}

	if fwd := r.Header.Get(forwarded); fwd != "" {
		// match should contain at least two elements if the protocol was
		// specified in the Forwarded header. The first element will always be
		// the 'for=' capture.
		matches := forRegex.FindAllStringSubmatch(fwd, -1)
		for _, match := range matches {
			if len(match) > 1 {
				// IPv6 addresses in Forwarded headers are quoted-strings. We strip
				// these quotes.
				addresses = append(addresses, strings.Trim(match[1], `"`))
			}
		}
	} else if fwd := r.Header.Get(xRealIP); fwd != "" {
		// X-Real-IP should only contain one IP address (the client making the
		// request).
		addresses = append(addresses, fwd)
	} else if fwd := r.Header.Get(xForwardedFor); fwd != "" {
		// It's possible that the header contains a list of addresses with a comma
		// delimiter and optional spaces.
		for _, addr := range strings.Split(fwd, ",") {
			trimmed := strings.Trim(addr, " ")
			if trimmed != "" {
				addresses = append(addresses, trimmed)
			}
			if !sips.extractAllHosts {
				break
			}
		}
	}

	return addresses
}
```

