// Provenance-includes-location: https://github.com/weaveworks/common/blob/main/middleware/source_ips.go
// Provenance-includes-license: Apache-2.0
// Provenance-includes-copyright: Weaveworks Ltd.

package middleware

import (
	"fmt"
	"net"
	"net/http"
	"regexp"
	"strings"
)

// Parts copied and changed from gorilla mux proxy_headers.go

var (
	// De-facto standard header keys.
	xForwardedFor = http.CanonicalHeaderKey("X-Forwarded-For")
	xRealIP       = http.CanonicalHeaderKey("X-Real-IP")
)

var (
	// RFC7239 defines a new "Forwarded: " header designed to replace the
	// existing use of X-Forwarded-* headers.
	// e.g. Forwarded: for=192.0.2.60;proto=https;by=203.0.113.43
	forwarded = http.CanonicalHeaderKey("Forwarded")
	// Allows for a sub-match of the value after 'for=' to the next
	// comma, semi-colon or space. The match is case-insensitive. Both quoted
	// (e.g. for="[2001:db8:cafe::17]:4711") and unquoted (e.g.
	// for=192.0.2.60) values are matched.
	forRegex = regexp.MustCompile(`(?i)(?:for=)((?:"[^"]*")|(?:[^;,\s]+))`)
	// Matches a single host/address in a comma-separated list of hosts (e.g.
	// the X-Forwarded-For header), stripping any surrounding spaces and quotes.
	xForwardedForRegex = regexp.MustCompile(`(?: *"?"([^,]+)"?" *)`)
)

// SourceIPExtractor extracts the source IPs from a HTTP request
type SourceIPExtractor struct {
	// The header to search for
	header string
	// A regex that extracts the IP address from the header.
	// It should contain at least one capturing group the first of which will be returned.
	regex *regexp.Regexp
	// Whether to extract all addresses from the headers (for informational
	// purposes) instead of only the first (originating) one.
	extractAllHosts bool
}

// NewSourceIPs creates a new SourceIPs
func NewSourceIPs(header, regex string, extractAllHosts bool) (*SourceIPExtractor, error) {
	if (header == "" && regex != "") || (header != "" && regex == "") {
		return nil, fmt.Errorf("either both a header field and a regex have to be given or neither")
	}
	re, err := regexp.Compile(regex)
	if err != nil {
		return nil, fmt.Errorf("invalid regex given")
	}

	return &SourceIPExtractor{
		header:          header,
		regex:           re,
		extractAllHosts: extractAllHosts,
	}, nil
}

// extractHost returns the Host IP address without any port information
func extractHost(address string) string {
	hostIP := net.ParseIP(address)
	if hostIP != nil {
		return hostIP.String()
	}
	var err error
	hostStr, _, err := net.SplitHostPort(address)
	if err != nil {
		// Invalid IP address, just return it so it shows up in the logs
		return address
	}
	return hostStr
}

// Get returns any source addresses we can find in the request, comma-separated
func (sips SourceIPExtractor) Get(req *http.Request) string {
	var result []string

	for _, fwd := range sips.getIP(req) {
		if fwd != "" {
			result = append(result, extractHost(fwd))
		}
		if !sips.extractAllHosts {
			break
		}
	}

	// If RemoteAddr is empty just return the header
	if req.RemoteAddr != "" {
		remoteIP := extractHost(req.RemoteAddr)
		// Only append the remote address if it's not already in the list
		alreadyIncluded := false
		for _, r := range result {
			if r == remoteIP {
				alreadyIncluded = true
				break
			}
		}
		if !alreadyIncluded {
			result = append(result, remoteIP)
		}
	}

	return strings.Join(result, ", ")
}

// getIP retrieves the IPs from the RFC7239 Forwarded headers,
// X-Real-IP and X-Forwarded-For (in that order) or from the
// custom regex. If extractAllHosts is disabled only the first
// (originating) address is returned, matching the previous behaviour.
func (sips SourceIPExtractor) getIP(r *http.Request) []string {
	var addresses []string

	// Use the custom regex only if it was setup
	if sips.header != "" {
		hdr := r.Header.Get(sips.header)
		if hdr == "" {
			return nil
		}
		limit := 1
		if sips.extractAllHosts {
			limit = -1
		}
		allMatches := sips.regex.FindAllStringSubmatch(hdr, limit)
		if len(allMatches) == 0 {
			return nil
		}
		for _, match := range allMatches {
			// Check there is at least 1 submatch
			if len(match) < 2 {
				continue
			}
			addresses = append(addresses, match[1])
		}
		return addresses
	}

	if fwd := r.Header.Get(forwarded); fwd != "" {
		// match should contain at least two elements if the protocol was
		// specified in the Forwarded header. The first element will always be
		// the 'for=' capture, which we ignore. In the case of multiple IP
		// addresses (for=8.8.8.8, 8.8.4.4,172.16.1.20 is valid) we extract all
		// of them.
		for _, match := range forRegex.FindAllStringSubmatch(fwd, -1) {
			if len(match) > 1 {
				// IPv6 addresses in Forwarded headers are quoted-strings. We strip
				// these quotes.
				addresses = append(addresses, strings.Trim(match[1], `"`))
			}
		}
	} else if fwd := r.Header.Get(xRealIP); fwd != "" {
		// X-Real-IP should only contain one IP address (the client making the
		// request).
		addresses = append(addresses, fwd)
	} else if fwd := r.Header.Get(xForwardedFor); fwd != "" {
		// It's possible that the header contains a list of addresses. We
		// extract the first (client) address by default, but if configured we
		// extract all of them. Note that '192.168.0.1, 10.1.1.1' is a valid key
		// for X-Forwarded-For where addresses after the first may represent
		// forwarding proxies earlier in the chain.
		limit := 1
		if sips.extractAllHosts {
			limit = -1
		}
		for _, match := range xForwardedForRegex.FindAllStringSubmatch(fwd, limit) {
			if len(match) > 1 {
				addresses = append(addresses, match[1])
			}
		}
	}

	return addresses
}

