+				RemoteAddr: "192.168.1.100:3454",
+				Header: map[string][]string{
+					http.CanonicalHeaderKey(xForwardedFor): {"192.168.1.100"},
+				},
+			},
+			want: "192.168.1.100",
+		},
+		{
+			name: "X-Forwarded-For with multiple addresses",
