+			},
+			want: "192.169.1.200, 192.168.1.100",
+		},
+		{
+			name: "Forwarded with multiple addresses",
+			req: &http.Request{
+				RemoteAddr: "192.168.1.100:3454",
+				Header: map[string][]string{
+					http.CanonicalHeaderKey(forwarded): {"for=192.169.1.200,for=10.10.13.20,for=10.11.16.46"},
+				},
+			},
+			want: "192.169.1.200, 10.10.13.20, 10.11.16.46, 192.168.1.100",
+		},
+		{
+			name: "Forwarded with multiple addresses and spaces",
+			req: &http.Request{
+				RemoteAddr: "192.168.1.100:3454",
+				Header: map[string][]string{
+					http.CanonicalHeaderKey(forwarded): {"for=192.169.1.200, for=10.10.13.20"},
+				},
