+			want: "192.169.1.200, 10.10.13.20, 192.168.1.100",
+		},
+		{
+			name: "Forwarded with uppercase For is case insensitive",
+			req: &http.Request{
+				RemoteAddr: "192.168.1.100:3454",
+				Header: map[string][]string{
+					http.CanonicalHeaderKey(forwarded): {"For=192.169.1.200, For=10.10.13.20"},
+				},
