arguments.content:
syntax = "proto3";

package ring;

import "github.com/gogo/protobuf/gogoproto/gogo.proto";

option (gogoproto.marshaler_all) = true;
option (gogoproto.unmarshaler_all) = true;

// PartitionRingDesc holds the full state of the partition ring.
message PartitionRingDesc {
	map<int32, PartitionDesc> partitions = 1 [(gogoproto.nullable) = false];

	map<string, OwnerDesc> owners = 2 [(gogoproto.nullable) = false];
}

// PartitionDesc holds the state of a single partition.
message PartitionDesc {
	repeated uint32 tokens = 1;

	PartitionState state = 2;

	// Unix timestamp (with seconds precision) of when the partition has been
	// created or updated.
	int64 stateTimestamp = 3;
}

// PartitionState is the state of a partition.
enum PartitionState {
	// PartitionUnknown is the state of a partition that has not been initialised yet.
	PartitionUnknown = 0;

	// PartitionActive is the state of a partition that is active and should be
	// able to both read and write data.
	PartitionActive = 1;

	// PartitionInactive is the state of a partition that is inactive, meaning it
	// should not receive new write requests, but must be able to serve read requests.
	PartitionInactive = 2;

	// PartitionDeleted is the state of a partition that has been deleted.
	// This state is only used by gossiping code to distribute information about
	// partitions that have been removed from the ring. Ring users should not use it directly.
	PartitionDeleted = 3;
}

// OwnerDesc holds the state of a single partition owner.
message OwnerDesc {
	int32 ownedPartition = 1;

	OwnerState state = 2;

	// Unix timestamp (with seconds precision) of when the owner has been
	// created or updated.
	int64 updatedTimestamp = 3;
}

// OwnerState is the state of a partition owner.
enum OwnerState {
	// OwnerUnknown is the state of an owner that has not been initialised yet.
	OwnerUnknown = 0;

	// OwnerActive is the state of an owner that is active, meaning it does own a partition.
	OwnerActive = 1;

